theorem sqrt_d_scale_bound {E : Type*}
    [NormedAddCommGroup E] [InnerProductSpace ℝ E] (q k : E) (d : ℝ) (hd : 0 < d) :
    |inner q k / Real.sqrt d| ≤ ‖q‖ * ‖k‖ / Real.sqrt d

theorem second_order_taylor {f : (Fin n → ℝ) → ℝ} {x v : Fin n → ℝ}
    {H : Matrix (Fin n) (Fin n) ℝ}
    (hg2 : deriv (deriv (path f x v)) 0 = quadForm H v) :
    ∃ R : ℝ, f (x + v)
      = f x + deriv (path f x v) 0 + (1 / 2) * quadForm H v + R
